public async Task<int> RecordAsync(AppReporter reporter, IReadOnlyList<ActivityUpload> uploads, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(reporter);
        ArgumentNullException.ThrowIfNull(uploads);
        Guard.That(uploads.Count is > 0 and <= 500, "activity.batch_size", "Send between 1 and 500 events at a time.");
        var now = clock.Now;

        // A reporter may batch events it saw earlier, but cannot write into the future.
        var events = uploads
            .Select(u => ActivityEvent.Record(reporter.Project.Id, u.SessionId, Min(u.At ?? now, now + MaxClockSkew), u.Kind, u.Summary, u.NodeIds))
            .ToList();
        await store.AppendAsync(events, ct).ConfigureAwait(false);
        return events.Count;
    }

public async Task<GraphView?> GetAsync(ProjectId id, UserId user, CancellationToken ct)
    {
        var project = await projects.LoadForMemberAsync(id, user, ct).ConfigureAwait(false);
        project.EnsureCan(user, Permission.ViewLiveGraph);
        var snapshot = await graphs.LatestAsync(id, ct).ConfigureAwait(false);
        if (snapshot is null)
        {
            return null;
        }

        var canSeeCode = project.Can(user, Permission.ViewCode);
        var nodes = canSeeCode ? snapshot.Nodes : snapshot.Nodes.Select(WithoutSource).ToList();
        var counts = Enum.GetValues<Severity>().ToDictionary(s => s, s => snapshot.Findings.Count(f => f.Severity == s));
        return new GraphView(snapshot.Commit, snapshot.IndexedAt, nodes, snapshot.Edges, canSeeCode ? snapshot.Findings : [], counts);
    }

public async Task<NodeDetail> GetNodeAsync(ProjectId id, string nodeId, UserId user, CancellationToken ct)
    {
        var project = await projects.LoadForMemberAsync(id, user, ct).ConfigureAwait(false);
        project.EnsureCan(user, Permission.ViewCode);
        var snapshot = await graphs.LatestAsync(id, ct).ConfigureAwait(false) ?? throw new NotFoundException("graph");
        var node = snapshot.Find(nodeId) ?? throw new NotFoundException("node");
        var explanations = await graphs.ExplanationsAsync(id, ct).ConfigureAwait(false);
        explanations.TryGetValue(nodeId, out var explanation);

        return new NodeDetail(
            node,
            explanation?.Text,
            explanation?.IsCurrentFor(node) ?? false,
            snapshot.Callers(nodeId).ToList(),
            snapshot.Callees(nodeId).ToList(),
            snapshot.CoveringTests(nodeId).ToList(),
            snapshot.EndpointsReaching(nodeId).ToList());
    }

