public static AuditEntry For(IDomainEvent domainEvent) => domainEvent switch
    {
        ApiKeyIssued e => new(e.ProjectId, e.By, "api_key.issued", $"key {e.KeyId} for environment {e.EnvironmentId}", e.OccurredAt),
        ApiKeyRevoked e => new(e.ProjectId, e.By, "api_key.revoked", $"key {e.KeyId}", e.OccurredAt),
        MemberChanged e => new(e.ProjectId, e.By, e.Role is null ? "member.removed" : "member.set", $"{e.Member} {e.Role}".Trim(), e.OccurredAt),
        EnvironmentKindChanged e => new(e.ProjectId, e.By, "environment.kind_changed", $"{e.EnvironmentId}: {e.From} -> {e.To}", e.OccurredAt),
        ProjectCreated e => new(e.ProjectId, e.Owner, "project.created", e.Name, e.OccurredAt),
        _ => throw new ArgumentOutOfRangeException(nameof(domainEvent), domainEvent.GetType().Name, "Not an audited event."),
    };

public static CodeGraphSnapshot Create(ProjectId projectId, string commit, DateTimeOffset indexedAt, IReadOnlyList<CodeNode> nodes, IReadOnlyList<CodeEdge> edges, IReadOnlyList<SecurityFinding>? findings = null)
    {
        ArgumentNullException.ThrowIfNull(nodes);
        ArgumentNullException.ThrowIfNull(edges);
        commit = Guard.NotBlank(commit, "graph.commit_required", "A graph snapshot needs the commit it was indexed from", 64);
        Guard.That(nodes.Count > 0, "graph.empty", "A graph snapshot needs at least one node.");

        var ids = new HashSet<string>(StringComparer.Ordinal);
        foreach (var node in nodes)
        {
            Guard.NotBlank(node.Id, "graph.node_id_required", "Every node needs an id", 1024);
            Guard.That(ids.Add(node.Id), "graph.duplicate_node", $"Node '{node.Id}' appears twice.");
        }

        foreach (var node in nodes.Where(n => n.ParentId is not null))
        {
            Guard.That(ids.Contains(node.ParentId!), "graph.unknown_parent", $"Node '{node.Id}' has an unknown parent '{node.ParentId}'.");
        }

        foreach (var edge in edges)
        {
            Guard.That(ids.Contains(edge.From) && ids.Contains(edge.To), "graph.dangling_edge", $"Edge {edge.From} -> {edge.To} points outside the graph.");
        }

        var checkedFindings = (findings ?? []).ToList();
        foreach (var finding in checkedFindings)
        {
            Guard.That(ids.Contains(finding.NodeId), "graph.finding_unknown_node", $"Finding '{finding.Rule}' points at unknown node '{finding.NodeId}'.");
            Guard.NotBlank(finding.Title, "graph.finding_title_required", "Every finding needs a title", 200);
        }

        var ordered = checkedFindings.OrderByDescending(f => f.Severity).ThenBy(f => f.Rule, StringComparer.Ordinal).ToList();
        return new CodeGraphSnapshot(projectId, commit, indexedAt, nodes, edges.Distinct().ToList(), ordered);
    }

public IEnumerable<CodeNode> EndpointsReaching(string id)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal) { id };
        var queue = new Queue<string>([id]);
        var endpoints = new List<CodeNode>();
        while (queue.Count > 0)
        {
            var current = queue.Dequeue();
            foreach (var edge in Edges.Where(e => e.To == current && e.Kind is EdgeKind.Calls or EdgeKind.HandledBy))
            {
                if (!seen.Add(edge.From))
                {
                    continue;
                }

                if (Find(edge.From) is { Kind: NodeKind.Endpoint } endpoint)
                {
                    endpoints.Add(endpoint);
                }

                queue.Enqueue(edge.From);
            }
        }

        return endpoints;
    }

public static string NotBlank(string? value, string code, string message, int maxLength = int.MaxValue)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new DomainException(code, message);
        }

        var trimmed = value.Trim();
        if (trimmed.Length > maxLength)
        {
            throw new DomainException(code, $"{message} (at most {maxLength} characters).");
        }

        return trimmed;
    }

public static void That(bool condition, string code, string message)
    {
        if (!condition)
        {
            throw new DomainException(code, message);
        }
    }

public void Approve(string optionKey, Project project, UserId by, DateTimeOffset now, string? note = null)
    {
        Resolve(project, by);
        Guard.That(Options.Any(o => o.Key == optionKey), "decision.unknown_option", "Choose one of the offered options.");
        Status = DecisionStatus.Approved;
        ChosenKey = optionKey;
        Finish(by, now, note);
    }

private void Finish(UserId by, DateTimeOffset now, string? note)
    {
        ResolvedBy = by;
        ResolvedAt = now;
        Note = note;
        Raise(new DecisionResolvedEvent(ProjectId, Id, Status, ChosenKey, by, now));
    }

public static Decision Propose(ProjectId projectId, DecisionArea area, string title, string context, IReadOnlyList<DecisionOption> options, string recommendedKey, DateTimeOffset now, DecisionId? supersedes = null)
    {
        ArgumentNullException.ThrowIfNull(options);
        title = Guard.NotBlank(title, "decision.title_required", "A decision needs a title", 120);
        context = Guard.NotBlank(context, "decision.context_required", "A decision needs context", 2000);
        Guard.That(options.Count is >= 2 and <= 3, "decision.option_count", "A decision offers two or three options.");
        Guard.That(options.Select(o => o.Key).Distinct(StringComparer.Ordinal).Count() == options.Count, "decision.duplicate_option", "Option keys must be unique.");
        Guard.That(options.Any(o => o.Key == recommendedKey), "decision.unknown_recommendation", "The recommendation must be one of the options.");

        var decision = new Decision(DecisionId.New(), projectId, area, title, context, options, recommendedKey, supersedes, now);
        decision.Raise(new DecisionProposedEvent(projectId, decision.Id, title, now));
        return decision;
    }

public void Reject(Project project, UserId by, DateTimeOffset now, string note)
    {
        Resolve(project, by);
        Status = DecisionStatus.Rejected;
        Finish(by, now, Guard.NotBlank(note, "decision.reason_required", "Say why it was rejected", 1000));
    }

private void Resolve(Project project, UserId by)
    {
        ArgumentNullException.ThrowIfNull(project);
        Guard.That(project.Id == ProjectId, "decision.wrong_project", "This decision belongs to another project.");
        Guard.That(Status == DecisionStatus.Proposed, "decision.already_resolved", "This decision is already resolved; propose a new one to change it.");
        project.EnsureCan(by, Permission.ApproveDecisions);
    }

internal static (ApiKey Key, string PlainText) Issue(EnvironmentId environmentId, DateTimeOffset now)
    {
        var prefix = Base64Url(RandomNumberGenerator.GetBytes(PrefixBytes));
        var secret = Base64Url(RandomNumberGenerator.GetBytes(SecretBytes));
        var plain = $"{Scheme}_{prefix}_{secret}";
        return (new ApiKey(ApiKeyId.New(), environmentId, prefix, HashOf(plain), now), plain);
    }

public bool Matches(string presented, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(presented);
        var presentedHash = Convert.FromHexString(HashOf(presented));
        var storedHash = Convert.FromHexString(Hash);
        return CryptographicOperations.FixedTimeEquals(presentedHash, storedHash) && IsActive(now);
    }

public static string? PrefixOf(string? presented)
    {
        if (string.IsNullOrEmpty(presented))
        {
            return null;
        }

        var parts = presented.Split('_', 3);
        return parts.Length == 3 && parts[0] == Scheme && parts[1].Length > 0 && parts[2].Length > 0 ? parts[1] : null;
    }

