public static int Run(Assembly assembly)
    {
        var tests = assembly.GetTypes()
            .Where(t => t.Name.EndsWith("Tests", StringComparison.Ordinal))
            .SelectMany(t => t.GetMethods(BindingFlags.Public | BindingFlags.Static).Where(m => m.GetParameters().Length == 0))
            .OrderBy(m => m.DeclaringType!.Name).ThenBy(m => m.Name)
            .ToList();

        var failed = 0;
        foreach (var test in tests)
        {
            var name = $"{test.DeclaringType!.Name}.{test.Name}";
            try
            {
                test.Invoke(null, null);
                Console.WriteLine($"  pass  {name}");
            }
            catch (TargetInvocationException ex)
            {
                failed++;
                Console.WriteLine($"  FAIL  {name}: {ex.InnerException?.Message}");
            }
        }

        Console.WriteLine($"{tests.Count - failed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }

public static string HeadCommit(string root)
    {
        try
        {
            using var git = Process.Start(new ProcessStartInfo("git", ["-C", root, "rev-parse", "--short=12", "HEAD"])
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
            })!;
            var sha = git.StandardOutput.ReadToEnd().Trim();
            git.WaitForExit();
            return git.ExitCode == 0 && sha.Length > 0 ? sha : "uncommitted";
        }
        catch (System.ComponentModel.Win32Exception)
        {
            return "uncommitted";
        }
    }

private static IEnumerable<string> ChainedGuards(InvocationExpressionSyntax mapCall, SemanticModel model)
    {
        SyntaxNode current = mapCall;
        while (current.Parent is MemberAccessExpressionSyntax { Parent: InvocationExpressionSyntax outer } access && access.Expression == current)
        {
            var name = access.Name.Identifier.Text;
            if (GuardMethods.Contains(name))
            {
                yield return GuardLabel(outer, name, model);
            }

            current = outer;
        }
    }

private SecurityFinding CodeFinding(SyntaxNode at, SemanticModel model, Module module, string file, string rule, Severity severity, string title, string why, string fix)
    {
        var nodeId = EnclosingNodeId(at, model, module);
        return new SecurityFinding
        {
            Rule = rule, Severity = severity, NodeId = nodeId, Title = title, Why = why, Fix = fix,
            File = Rel(file), Line = at.GetLocation().GetLineSpan().StartLinePosition.Line + 1,
        };
    }

private void CollectEdges(SyntaxTree tree, SemanticModel model, Module module)
    {
        var rootNode = tree.GetRoot();

        foreach (var method in rootNode.DescendantNodes().OfType<MethodDeclarationSyntax>())
        {
            if (model.GetDeclaredSymbol(method) is IMethodSymbol symbol && IdOf(symbol) is { } from && _nodes.TryGetValue(from, out var node))
            {
                LinkCalls(from, method, model, node.Kind == NodeKind.Test);
            }
        }

        var globals = rootNode.ChildNodes().OfType<GlobalStatementSyntax>().ToList();
        foreach (var global in globals)
        {
            LinkCalls(StartupId(module), global, model, isTest: false);
        }

        foreach (var type in rootNode.DescendantNodes().OfType<TypeDeclarationSyntax>())
        {
            if (model.GetDeclaredSymbol(type) is INamedTypeSymbol symbol && IdOf(symbol) is { } typeId && _nodes.ContainsKey(typeId))
            {
                LinkTypeDependencies(typeId, symbol);
            }
        }

        foreach (var invocation in rootNode.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            LinkEndpointHandler(invocation, model);
        }
    }

private void CollectNodes(SyntaxTree tree, SemanticModel model, Module module)
    {
        var rootNode = tree.GetRoot();
        var file = tree.FilePath;

        foreach (var type in rootNode.DescendantNodes().OfType<BaseTypeDeclarationSyntax>())
        {
            if (model.GetDeclaredSymbol(type) is not INamedTypeSymbol symbol || IdOf(symbol) is not { } id)
            {
                continue;
            }

            var parent = symbol.ContainingType is { } outer && IdOf(outer) is { } outerId ? outerId : ParentFor(file, module);
            Add(Located(new CodeNode { Id = id, Kind = NodeKind.Type, Name = symbol.Name, ParentId = parent }, type, file, withCode: false));
        }

        foreach (var method in rootNode.DescendantNodes().OfType<MethodDeclarationSyntax>())
        {
            if (model.GetDeclaredSymbol(method) is not IMethodSymbol symbol || IdOf(symbol) is not { } id || IdOf(symbol.ContainingType) is not { } typeId)
            {
                continue;
            }

            var isTest = module.IsTest && symbol.DeclaredAccessibility == Accessibility.Public && symbol.ContainingType.Name.EndsWith("Tests", StringComparison.Ordinal);
            Add(Located(new CodeNode { Id = id, Kind = isTest ? NodeKind.Test : NodeKind.Method, Name = symbol.Name, ParentId = typeId }, method, file, withCode: true));
        }

        // Top-level statements (Program.cs) become one "startup" node per module, with the request pipeline as its guards.
        var globals = rootNode.ChildNodes().OfType<GlobalStatementSyntax>().ToList();
        if (globals.Count > 0)
        {
            var pipeline = globals.SelectMany(g => g.DescendantNodes().OfType<InvocationExpressionSyntax>())
                .Select(MethodName).Where(n => n is not null && PipelineMethods.Contains(n)).Select(n => n!).ToList();
            var span = globals[0].GetLocation().GetLineSpan();
            var end = globals[^1].GetLocation().GetLineSpan();
            var code = string.Join(Environment.NewLine, globals.Select(g => g.ToString()));
            Add(new CodeNode
            {
                Id = StartupId(module), Kind = NodeKind.Method, Name = "Startup", ParentId = module.Id, File = Rel(file),
                StartLine = span.StartLinePosition.Line + 1, EndLine = end.EndLinePosition.Line + 1,
                Code = code, CodeHash = CodeNode.HashCode(code), Guards = pipeline,
            });
        }

        foreach (var invocation in rootNode.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (Endpoint(invocation, model, module, file) is { } endpoint)
            {
                Add(endpoint);
            }
        }
    }

private string EnclosingNodeId(SyntaxNode at, SemanticModel model, Module module)
    {
        foreach (var ancestor in at.AncestorsAndSelf())
        {
            var symbol = ancestor switch
            {
                MethodDeclarationSyntax m => model.GetDeclaredSymbol(m) as ISymbol,
                BaseTypeDeclarationSyntax t => model.GetDeclaredSymbol(t),
                _ => null,
            };
            if (IdOf(symbol) is { } id && _nodes.ContainsKey(id))
            {
                return id;
            }

            if (ancestor is GlobalStatementSyntax && _nodes.ContainsKey(StartupId(module)))
            {
                return StartupId(module);
            }
        }

        return module.Id;
    }

private CodeNode? Endpoint(InvocationExpressionSyntax invocation, SemanticModel model, Module module, string file)
    {
        if (invocation.Expression is not MemberAccessExpressionSyntax access || !MapVerbs.Contains(access.Name.Identifier.Text))
        {
            return null;
        }

        if (invocation.ArgumentList.Arguments.FirstOrDefault()?.Expression is not LiteralExpressionSyntax { Token.Value: string template })
        {
            return null;
        }

        var (prefix, groupGuards) = GroupOf(access.Expression, model);
        var verb = access.Name.Identifier.Text["Map".Length..].ToUpperInvariant();
        var route = $"{verb} {JoinRoute(prefix, template)}";
        var guards = groupGuards.Concat(ChainedGuards(invocation, model)).Distinct().ToList();
        var container = invocation.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault();
        var parent = container is not null && model.GetDeclaredSymbol(container) is IMethodSymbol m && IdOf(m.ContainingType) is { } typeId
            ? typeId
            : ParentFor(file, module);
        var span = invocation.GetLocation().GetLineSpan();
        return new CodeNode
        {
            Id = EndpointId(route), Kind = NodeKind.Endpoint, Name = route, ParentId = parent, File = Rel(file),
            StartLine = span.StartLinePosition.Line + 1, EndLine = span.EndLinePosition.Line + 1, Route = route, Guards = guards,
        };
    }

private List<Module> FindModules() =>
        Directory.EnumerateFiles(root, "*.csproj", SearchOption.AllDirectories)
            .Where(f => !IsSkipped(f))
            .Select(f =>
            {
                var name = Path.GetFileNameWithoutExtension(f);
                return new Module($"module:{name}", name, Path.GetDirectoryName(f)!, f, name.EndsWith(".Tests", StringComparison.Ordinal));
            })
            .OrderBy(m => m.Name, StringComparer.Ordinal)
            .ToList();

private static SecurityFinding Finding(CodeNode node, string rule, Severity severity, string title, string why, string fix) => new()
    {
        Rule = rule, Severity = severity, NodeId = node.Id, Title = title, Why = why, Fix = fix, File = node.File, Line = node.StartLine,
    };

private static (string Prefix, List<string> Guards) GroupOf(ExpressionSyntax receiver, SemanticModel model)
    {
        var chain = receiver;
        if (receiver is IdentifierNameSyntax identifier
            && model.GetSymbolInfo(identifier).Symbol is ILocalSymbol local
            && local.DeclaringSyntaxReferences.FirstOrDefault()?.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } init })
        {
            chain = init;
        }

        var prefix = string.Empty;
        var guards = new List<string>();
        foreach (var call in chain.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>())
        {
            var name = MethodName(call);
            if (name == "MapGroup" && call.ArgumentList.Arguments.FirstOrDefault()?.Expression is LiteralExpressionSyntax { Token.Value: string groupPrefix })
            {
                prefix = groupPrefix;
            }
            else if (name is not null && GuardMethods.Contains(name))
            {
                guards.Add(GuardLabel(call, name, model));
            }
        }

        guards.Reverse();
        return (prefix, guards);
    }

private static IEnumerable<InvocationExpressionSyntax> GuardCalls(ExpressionSyntax receiver, InvocationExpressionSyntax mapCall, SemanticModel model)
    {
        var chain = receiver;
        if (receiver is IdentifierNameSyntax identifier
            && model.GetSymbolInfo(identifier).Symbol is ILocalSymbol local
            && local.DeclaringSyntaxReferences.FirstOrDefault()?.GetSyntax() is VariableDeclaratorSyntax { Initializer.Value: { } init })
        {
            chain = init;
        }

        var calls = chain.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().ToList();
        SyntaxNode current = mapCall;
        while (current.Parent is MemberAccessExpressionSyntax { Parent: InvocationExpressionSyntax outer } access && access.Expression == current)
        {
            calls.Add(outer);
            current = outer;
        }

        return calls.Where(c => MethodName(c) is { } n && GuardMethods.Contains(n));
    }

private static string GuardLabel(InvocationExpressionSyntax call, string name, SemanticModel model)
    {
        var argument = call.ArgumentList.Arguments.FirstOrDefault()?.Expression;
        if (argument is null)
        {
            return name;
        }

        return model.GetConstantValue(argument) is { HasValue: true, Value: string value }
            ? $"{name}:{value}"
            : argument is MemberAccessExpressionSyntax m ? $"{name}:{m.Name.Identifier.Text}" : name;
    }

private static string? HolderName(LiteralExpressionSyntax literal) => literal.Parent switch
    {
        EqualsValueClauseSyntax { Parent: VariableDeclaratorSyntax v } => v.Identifier.Text,
        EqualsValueClauseSyntax { Parent: PropertyDeclarationSyntax p } => p.Identifier.Text,
        AssignmentExpressionSyntax a => a.Left.ToString().Split('.').Last(),
        _ => null,
    };

private static SyntaxTree ImplicitUsings() => CSharpSyntaxTree.ParseText("""
        global using System;
        global using System.Collections.Generic;
        global using System.IO;
        global using System.Linq;
        global using System.Net.Http;
        global using System.Net.Http.Json;
        global using System.Threading;
        global using System.Threading.Tasks;
        global using Microsoft.AspNetCore.Builder;
        global using Microsoft.AspNetCore.Hosting;
        global using Microsoft.AspNetCore.Http;
        global using Microsoft.AspNetCore.Routing;
        global using Microsoft.Extensions.Configuration;
        global using Microsoft.Extensions.DependencyInjection;
        global using Microsoft.Extensions.Hosting;
        global using Microsoft.Extensions.Logging;
        """, path: "monday-implicit-usings.g.cs");

public GraphFile Index(string commit)
    {
        Add(new CodeNode { Id = AppId, Kind = NodeKind.App, Name = appName });

        var modules = FindModules();
        var trees = new List<(SyntaxTree Tree, Module Module)>();
        foreach (var module in modules)
        {
            Add(new CodeNode { Id = module.Id, Kind = NodeKind.Module, Name = module.Name, ParentId = AppId, File = Rel(module.ProjectFile) });
            foreach (var file in SourceFiles(module.Dir))
            {
                trees.Add((CSharpSyntaxTree.ParseText(File.ReadAllText(file), path: file), module));
            }
        }

        var compilation = CSharpCompilation.Create(
            "monday-index",
            trees.Select(t => t.Tree).Append(ImplicitUsings()),
            References(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Enable));

        // Pass 1: nodes. Pass 2: edges (needs every node to exist first).
        foreach (var (tree, module) in trees)
        {
            CollectNodes(tree, compilation.GetSemanticModel(tree), module);
        }

        foreach (var (tree, module) in trees)
        {
            CollectEdges(tree, compilation.GetSemanticModel(tree), module);
        }

        var nodes = _nodes.Values.OrderBy(n => n.Kind).ThenBy(n => n.Id, StringComparer.Ordinal).ToList();
        var edges = _edges.Where(e => e.From != e.To).OrderBy(e => e.From, StringComparer.Ordinal).ThenBy(e => e.To, StringComparer.Ordinal).ToList();
        var findings = ScanEndpointsAndPipeline();
        foreach (var (tree, module) in trees)
        {
            findings.AddRange(ScanCode(tree, compilation.GetSemanticModel(tree), module));
        }

        return new GraphFile(commit, nodes, edges, findings.OrderByDescending(f => f.Severity).ThenBy(f => f.NodeId, StringComparer.Ordinal).ToList());
    }

private static bool IsManagedAssembly(string path)
    {
        try
        {
            System.Reflection.AssemblyName.GetAssemblyName(path);
            return true;
        }
        catch (BadImageFormatException)
        {
            return false;
        }
    }

private static string JoinRoute(string prefix, string template)
    {
        var joined = $"/{prefix.Trim('/')}/{template.Trim('/')}".Replace("//", "/", StringComparison.Ordinal);
        return joined.Length > 1 ? joined.TrimEnd('/') : joined;
    }

private void LinkCalls(string from, SyntaxNode body, SemanticModel model, bool isTest)
    {
        foreach (var call in body.DescendantNodes().Where(n => n is InvocationExpressionSyntax or ObjectCreationExpressionSyntax or ImplicitObjectCreationExpressionSyntax))
        {
            if (model.GetSymbolInfo(call).Symbol is not IMethodSymbol target || TargetId(target) is not { } to)
            {
                continue;
            }

            var kind = isTest && _nodes[to].Kind != NodeKind.Test ? EdgeKind.Covers : EdgeKind.Calls;
            _edges.Add(new CodeEdge(from, to, kind));
        }
    }

private void LinkEndpointHandler(InvocationExpressionSyntax invocation, SemanticModel model)
    {
        if (invocation.Expression is not MemberAccessExpressionSyntax access || !MapVerbs.Contains(access.Name.Identifier.Text)
            || invocation.ArgumentList.Arguments.Count < 2
            || invocation.ArgumentList.Arguments[0].Expression is not LiteralExpressionSyntax { Token.Value: string template })
        {
            return;
        }

        var (prefix, _) = GroupOf(access.Expression, model);
        var endpointId = EndpointId($"{access.Name.Identifier.Text["Map".Length..].ToUpperInvariant()} {JoinRoute(prefix, template)}");
        // Guards written in this repo (like RequireReporterKey) run on every request: link them so the path shows them.
        foreach (var guardCall in GuardCalls(access.Expression, invocation, model))
        {
            if (model.GetSymbolInfo(guardCall).Symbol is IMethodSymbol guard && TargetId(guard) is { } guardId)
            {
                _edges.Add(new CodeEdge(endpointId, guardId, EdgeKind.Calls));
            }
        }

        var handler = invocation.ArgumentList.Arguments[1].Expression;
        if (handler is LambdaExpressionSyntax lambda)
        {
            LinkCalls(endpointId, lambda, model, isTest: false);
            return;
        }

        var symbolInfo = model.GetSymbolInfo(handler);
        var target = symbolInfo.Symbol as IMethodSymbol ?? symbolInfo.CandidateSymbols.OfType<IMethodSymbol>().FirstOrDefault();
        if (target is not null && TargetId(target) is { } to)
        {
            _edges.Add(new CodeEdge(endpointId, to, EdgeKind.HandledBy));
        }
    }

private void LinkTypeDependencies(string typeId, INamedTypeSymbol symbol)
    {
        foreach (var iface in symbol.AllInterfaces)
        {
            if (IdOf(iface) is { } ifaceId && _nodes.ContainsKey(ifaceId))
            {
                _edges.Add(new CodeEdge(typeId, ifaceId, EdgeKind.Implements));
            }
        }

        var dependencies = symbol.Constructors.SelectMany(c => c.Parameters).Select(p => p.Type)
            .Concat(symbol.GetMembers().OfType<IFieldSymbol>().Select(f => f.Type));
        foreach (var dependency in dependencies)
        {
            var named = dependency as INamedTypeSymbol;
            if (named is not null && IdOf(named.OriginalDefinition) is { } depId && depId != typeId && _nodes.ContainsKey(depId))
            {
                _edges.Add(new CodeEdge(typeId, depId, EdgeKind.DependsOn));
            }
        }
    }

private CodeNode Located(CodeNode node, SyntaxNode syntax, string file, bool withCode)
    {
        var span = syntax.GetLocation().GetLineSpan();
        var code = withCode ? syntax.ToString() : null;
        return node with
        {
            File = Rel(file),
            StartLine = span.StartLinePosition.Line + 1,
            EndLine = span.EndLinePosition.Line + 1,
            Code = code,
            CodeHash = code is null ? null : CodeNode.HashCode(code),
        };
    }

private static string? MethodName(InvocationExpressionSyntax call) => call.Expression switch
    {
        MemberAccessExpressionSyntax m => m.Name.Identifier.Text,
        IdentifierNameSyntax i => i.Identifier.Text,
        GenericNameSyntax g => g.Identifier.Text,
        _ => null,
    };

private string? ModuleOf(CodeNode node)
    {
        var current = node;
        while (current is not null && current.Kind != NodeKind.Module)
        {
            current = current.ParentId is { } p && _nodes.TryGetValue(p, out var parent) ? parent : null;
        }

        return current?.Id;
    }

private string ParentFor(string file, Module module)
    {
        var relative = Path.GetRelativePath(module.Dir, file).Split(Path.DirectorySeparatorChar);
        if (relative.Length < 2)
        {
            return module.Id;
        }

        var featureId = $"feature:{module.Name}/{relative[0]}";
        if (!_nodes.ContainsKey(featureId))
        {
            Add(new CodeNode { Id = featureId, Kind = NodeKind.Feature, Name = relative[0], ParentId = module.Id, File = Rel(Path.Combine(module.Dir, relative[0])) });
        }

        return featureId;
    }

private static IEnumerable<MetadataReference> References()
    {
        var netcore = Path.GetDirectoryName(typeof(object).Assembly.Location)!;
        var version = new DirectoryInfo(netcore).Name;
        var shared = Directory.GetParent(netcore)!.Parent!.FullName;
        var aspnet = Path.Combine(shared, "Microsoft.AspNetCore.App", version);
        if (!Directory.Exists(aspnet))
        {
            aspnet = Directory.EnumerateDirectories(Path.Combine(shared, "Microsoft.AspNetCore.App")).OrderDescending().FirstOrDefault() ?? string.Empty;
        }

        return new[] { netcore, aspnet }
            .Where(Directory.Exists)
            .SelectMany(d => Directory.EnumerateFiles(d, "*.dll"))
            .Where(IsManagedAssembly)
            .GroupBy(Path.GetFileName)
            .Select(g => MetadataReference.CreateFromFile(g.First()));
    }

private static bool ReturnsTrue(ExpressionSyntax expression) => expression switch
    {
        LambdaExpressionSyntax { ExpressionBody: LiteralExpressionSyntax lit } => lit.IsKind(SyntaxKind.TrueLiteralExpression),
        LambdaExpressionSyntax { Block: { } block } => block.Statements.Count == 1 && block.Statements[0] is ReturnStatementSyntax { Expression: LiteralExpressionSyntax r } && r.IsKind(SyntaxKind.TrueLiteralExpression),
        _ => false,
    };

private IEnumerable<SecurityFinding> ScanCode(SyntaxTree tree, SemanticModel model, Module module)
    {
        var rootNode = tree.GetRoot();
        var file = tree.FilePath;

        foreach (var invocation in rootNode.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            var name = MethodName(invocation);
            if (name is not null && RawSqlMethods.Contains(name) && invocation.ArgumentList.Arguments.FirstOrDefault()?.Expression is { } sql && IsBuiltString(sql))
            {
                yield return CodeFinding(invocation, model, module, file, "sql-built-from-strings", Severity.High,
                    $"{name} runs SQL built from strings",
                    "If any part comes from a request, an attacker can change the query (SQL injection).",
                    "Use FromSql/ExecuteSql with an interpolated FormattableString, or parameters.");
            }

            if (invocation.Expression is MemberAccessExpressionSyntax { Expression: IdentifierNameSyntax { Identifier.Text: "MD5" or "SHA1" } weak })
            {
                yield return CodeFinding(invocation, model, module, file, "weak-hash", Severity.Medium,
                    $"{weak.Identifier.Text} is used",
                    $"{weak.Identifier.Text} is broken for security uses: collisions can be forged.",
                    "Use SHA256 or better; for passwords use a password hasher (PBKDF2, bcrypt, Argon2).");
            }

            if (name == "AllowAnyOrigin")
            {
                var chain = invocation.Ancestors().OfType<InvocationExpressionSyntax>().LastOrDefault() ?? invocation;
                var withCredentials = chain.DescendantNodesAndSelf().OfType<InvocationExpressionSyntax>().Any(i => MethodName(i) == "AllowCredentials");
                yield return CodeFinding(invocation, model, module, file, "cors-any-origin", withCredentials ? Severity.High : Severity.Medium,
                    withCredentials ? "CORS allows any site, with credentials" : "CORS allows any site",
                    "Any website can call this API from a visitor's browser" + (withCredentials ? ", carrying their sign-in." : "."),
                    "List the exact origins that need access with WithOrigins(...).");
            }
        }

        foreach (var creation in rootNode.DescendantNodes().OfType<ObjectCreationExpressionSyntax>())
        {
            var typeName = creation.Type switch
            {
                IdentifierNameSyntax i => i.Identifier.Text,
                QualifiedNameSyntax q => q.Right.Identifier.Text,
                _ => null,
            };
            if (typeName is not null && SqlCommandTypes.Contains(typeName) && creation.ArgumentList?.Arguments.FirstOrDefault()?.Expression is { } sql && IsBuiltString(sql))
            {
                yield return CodeFinding(creation, model, module, file, "sql-built-from-strings", Severity.High,
                    $"{typeName} runs SQL built from strings",
                    "If any part comes from a request, an attacker can change the query (SQL injection).",
                    "Use command parameters (@name) instead of putting values into the SQL text.");
            }
        }

        foreach (var assignment in rootNode.DescendantNodes().OfType<AssignmentExpressionSyntax>())
        {
            var target = assignment.Left.ToString();
            if ((target.EndsWith("ServerCertificateCustomValidationCallback", StringComparison.Ordinal) || target.EndsWith("RemoteCertificateValidationCallback", StringComparison.Ordinal))
                && (assignment.Right.ToString().Contains("DangerousAcceptAnyServerCertificateValidator", StringComparison.Ordinal) || ReturnsTrue(assignment.Right)))
            {
                yield return CodeFinding(assignment, model, module, file, "tls-validation-off", Severity.High,
                    "TLS certificate checks are turned off",
                    "Anyone between the app and the server can impersonate it and read or change the traffic.",
                    "Remove the callback; fix the certificate or trust store instead.");
            }
        }

        foreach (var literal in rootNode.DescendantNodes().OfType<LiteralExpressionSyntax>().Where(l => l.IsKind(SyntaxKind.StringLiteralExpression)))
        {
            if (literal.Token.ValueText is not { Length: >= 8 } value)
            {
                continue;
            }

            var holder = HolderName(literal);
            var looksSecret = SecretValue().IsMatch(value) || (holder is not null && SecretName().IsMatch(holder) && !value.Contains(' ', StringComparison.Ordinal) && !value.StartsWith("X-", StringComparison.Ordinal));
            if (looksSecret)
            {
                yield return CodeFinding(literal, model, module, file, "hardcoded-secret", module.IsTest ? Severity.Medium : Severity.High,
                    holder is null ? "A secret-looking value is written in the code" : $"'{holder}' holds a value written in the code",
                    "Anyone with the code (or a leaked copy) gets the secret, and it can't be rotated without a release.",
                    "Read it from configuration or a secret store; rotate the exposed value.");
            }
        }
    }

private List<SecurityFinding> ScanEndpointsAndPipeline()
    {
        var findings = new List<SecurityFinding>();
        var endpoints = _nodes.Values.Where(n => n.Kind == NodeKind.Endpoint).ToList();

        foreach (var ep in endpoints)
        {
            var verb = ep.Route!.Split(' ')[0];
            var anonymous = ep.Guards.Contains("AllowAnonymous");
            var authed = !anonymous && ep.Guards.Any(IsAuthGuard);
            var limited = ep.Guards.Any(g => g.StartsWith("RequireRateLimiting", StringComparison.Ordinal));

            // A sign-in route has to be public; an explicit AllowAnonymous is a choice to review, not an oversight.
            if (!authed && WriteVerbs.Contains(verb) && !(anonymous && SensitiveRoute().IsMatch(ep.Route)))
            {
                findings.Add(Finding(ep, "write-without-auth", anonymous ? Severity.Medium : Severity.High,
                    anonymous ? $"{ep.Route} changes data and is marked public" : $"{ep.Route} changes data without sign-in",
                    "Anyone who can reach the API can call it. Writes are the first thing an attacker tries.",
                    anonymous ? "Confirm it must be public; otherwise remove .AllowAnonymous() and require sign-in." : "Add .RequireAuthorization() (or the project's key guard) to the endpoint or its group."));
            }

            if (!authed && !limited)
            {
                findings.Add(Finding(ep, "public-without-rate-limit", WriteVerbs.Contains(verb) ? Severity.Medium : Severity.Low,
                    $"{ep.Route} is public and has no rate limit",
                    "A public route without a limit can be flooded to slow the app down or to run up hosting costs.",
                    "Add .RequireRateLimiting(\"<policy>\") with a policy partitioned by client."));
            }

            if (SensitiveRoute().IsMatch(ep.Route) && !limited)
            {
                findings.Add(Finding(ep, "credential-route-without-rate-limit", Severity.Medium,
                    $"{ep.Route} looks like a sign-in or token route but has no rate limit",
                    "Without a limit, passwords and codes can be guessed by brute force.",
                    "Rate-limit by user and by IP, and lock out after repeated failures."));
            }

            if (!authed && ep.Guards.Contains("DisableAntiforgery"))
            {
                findings.Add(Finding(ep, "antiforgery-off-without-auth", Severity.Medium,
                    $"{ep.Route} turns off antiforgery without another guard",
                    "Browser form posts from other sites can reach this route on a signed-in user's behalf.",
                    "Keep antiforgery on, or require a key or token that browsers don't send automatically."));
            }
        }

        foreach (var startup in _nodes.Values.Where(n => n.Id.StartsWith("startup:", StringComparison.Ordinal)))
        {
            var moduleEndpoints = endpoints.Where(e => ModuleOf(e) == startup.ParentId).ToList();
            if (moduleEndpoints.Count == 0)
            {
                continue;
            }

            var pipeline = startup.Guards;
            if (!pipeline.Contains("UseHttpsRedirection"))
            {
                findings.Add(Finding(startup, "no-https-redirect", Severity.High, "Requests over plain HTTP are not redirected to HTTPS",
                    "Keys, cookies and data can travel unencrypted and be read on the way.", "Add app.UseHttpsRedirection() early in Program.cs."));
            }

            if (!pipeline.Contains("UseHsts"))
            {
                findings.Add(Finding(startup, "no-hsts", Severity.Medium, "Browsers aren't told to insist on HTTPS (no HSTS)",
                    "A first visit over HTTP can be intercepted and downgraded.", "Add app.UseHsts() outside Development."));
            }

            if (!pipeline.Contains("UseExceptionHandler"))
            {
                findings.Add(Finding(startup, "no-exception-handler", Severity.Low, "No central exception handler",
                    "Unhandled errors can leak stack traces and internal names to callers.", "Add app.UseExceptionHandler() with problem details."));
            }

            var authIndex = pipeline.ToList().IndexOf("UseAuthentication");
            var authzIndex = pipeline.ToList().IndexOf("UseAuthorization");
            if (authIndex >= 0 && authzIndex >= 0 && authzIndex < authIndex)
            {
                findings.Add(Finding(startup, "authorization-before-authentication", Severity.High, "Authorization runs before authentication",
                    "Policies are checked before the user is known, so they can fail open or always deny.", "Call app.UseAuthentication() before app.UseAuthorization()."));
            }

            if (moduleEndpoints.Any(e => e.Guards.Any(g => g.StartsWith("RequireRateLimiting", StringComparison.Ordinal))) && !pipeline.Contains("UseRateLimiter"))
            {
                findings.Add(Finding(startup, "rate-limiter-not-in-pipeline", Severity.High, "Endpoints ask for rate limits but the limiter isn't in the pipeline",
                    "The limits are silently not applied.", "Add app.UseRateLimiter() after routing and authentication."));
            }
        }

        return findings;
    }

private string? TargetId(IMethodSymbol target)
    {
        var declared = target.ReducedFrom ?? target;
        return IdOf(declared) is { } id && _nodes.ContainsKey(id) ? id : null;
    }

public static IServiceCollection AddMonday(this IServiceCollection services)
    {
        services.AddSingleton<IClock, SystemClock>();
        services.AddSingleton<IProjectRepository, InMemoryProjectRepository>();
        services.AddSingleton<IGraphStore, InMemoryGraphStore>();
        services.AddSingleton<IActivityStore, InMemoryActivityStore>();
        services.AddSingleton<IDecisionRepository, InMemoryDecisionRepository>();
        services.AddSingleton<IAuditLog, InMemoryAuditLog>();

        services.AddScoped<ApiKeyAuthenticator>();
        services.AddScoped<ProjectService>();
        services.AddScoped<GraphService>();
        services.AddScoped<ActivityService>();
        services.AddScoped<DecisionService>();
        return services;
    }

public Task AppendAsync(IReadOnlyList<ActivityEvent> events, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(events);
        lock (_gate)
        {
            _events.AddRange(events);
        }

        return Task.CompletedTask;
    }

public Task<IReadOnlyList<ActivityEvent>> RangeAsync(ProjectId project, DateTimeOffset since, DateTimeOffset until, CancellationToken ct)
    {
        lock (_gate)
        {
            return Task.FromResult<IReadOnlyList<ActivityEvent>>(
                _events.Where(e => e.ProjectId == project && e.At >= since && e.At <= until).OrderBy(e => e.At).ToList());
        }
    }

public Task AppendAsync(AuditEntry entry, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(entry);
        lock (_gate)
        {
            _entries.Add(entry);
        }

        return Task.CompletedTask;
    }

public Task<IReadOnlyList<AuditEntry>> ListAsync(ProjectId project, CancellationToken ct)
    {
        lock (_gate)
        {
            return Task.FromResult<IReadOnlyList<AuditEntry>>(_entries.Where(e => e.ProjectId == project).ToList());
        }
    }

public Task SaveAsync(Decision decision, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(decision);
        _decisions[decision.Id] = decision;
        return Task.CompletedTask;
    }

public Task<IReadOnlyDictionary<string, Explanation>> ExplanationsAsync(ProjectId project, CancellationToken ct) =>
        Task.FromResult<IReadOnlyDictionary<string, Explanation>>(
            _explanations.TryGetValue(project, out var map) ? new Dictionary<string, Explanation>(map) : new Dictionary<string, Explanation>());

public Task SaveAsync(CodeGraphSnapshot snapshot, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(snapshot);
        _latest[snapshot.ProjectId] = snapshot;
        return Task.CompletedTask;
    }

public Task SaveExplanationsAsync(ProjectId project, IReadOnlyList<Explanation> explanations, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(explanations);
        var map = _explanations.GetOrAdd(project, _ => new ConcurrentDictionary<string, Explanation>(StringComparer.Ordinal));
        foreach (var e in explanations)
        {
            map[e.NodeId] = e;
        }

        return Task.CompletedTask;
    }

public Task SaveAsync(Project project, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(project);
        _projects[project.Id] = project;
        return Task.CompletedTask;
    }

